style.css:
@-moz-document domain("roblox.com") {
body, .theme-bg, .content, .page-content, html {
        background: url("https://i.imgur.com/uxTIcIy.png") !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
    }

    /* Hacer fondos internos transparentes */
    .rbx-navbar, 
    .rbx-header, 
    .container-main, 
    .content,
    .theme-bg,
    .section,
    .game-home-page,
    .game-details-section,
    #navigation, 
    #footer-container,
    .app-home,
    .content-container {
        background: transparent !important;
    }

    /* Opcional: color del texto para que se vea bien */
    body, html, * {
        color: white !important;
        text-shadow: 0 0 3px black !important;
    }
}
